from collections import deque

def transform(grid):
    if not grid:
        return grid

    rows, cols = len(grid), len(grid[0])

    # Determine background color: the most frequent color. 
    # This typically corresponds to the "0" in the demo case and "1" in the test case.
    counts = {}
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            counts[val] = counts.get(val, 0) + 1

    bg_color = max(counts, key=counts.get)

    # Identify background color components that touch the border.
    # Any background color cell NOT visited by a flood fill from the border 
    # is considered "enclosed" or a "hole".

    visited = [[False] * cols for _ in range(rows)]
    q = deque()

    # Initialize BFS with border cells of the background color
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg_color and (r == 0 or r == rows - 1 or c == 0 or c == cols - 1):
                visited[r][c] = True
                q.append((r, c))

    # BFS to fill all connected background color regions starting from border
    while q:
        r, c = q.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited[nr][nc] and grid[nr][nc] == bg_color:
                    visited[nr][nc] = True
                    q.append((nr, nc))

    # Fill any remaining enclosed background color cells with 4 (Yellow)
    fill_color = 4
    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] == bg_color:
                grid[r][c] = fill_color

    return grid
